#include <stdio.h>
#include <stdlib.h>
int compare(const void *a, const void *b) {
 int x = *(const int *)a, y = *(const int *)b;
 return (x > y) - (x < y);
}
int main(void) {
 int values[] = {4, 1, 3};
 qsort(values, 3, sizeof values[0], compare);
 printf("%d\n", values[0]);
 return EXIT_SUCCESS;
}
